import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final numero=TextEditingController();String mensagem='';void calcular(){final n=int.tryParse(numero.text);setState(()=>mensagem=n==null?'Informe um número inteiro.':'Número: $n\nAntecessor: ${n-1}\nSucessor: ${n+1}');}void limpar(){numero.clear();setState(()=>mensagem='');}@override void dispose(){numero.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Antecessor e sucessor')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:numero,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Número inteiro')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:calcular,child:const Text('Calcular')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(mensagem)])));}
